/**
 * Pure view functions: state → markup string.
 * Only numbers / hex strings generated by the app are interpolated here (no user text),
 * so the output is safe to assign to innerHTML.
 */
import type { BlockInfo, Die } from '../core/dice';
import { sumOf, type Roll } from '../core/history';
import type { RegisterSnapshot } from '../crypto/katan';
import type { DiceColor } from '../core/settings';
import type { SumStat } from '../core/stats';

// ---------------------------------------------------------------------------
// dice

const PIPS: Readonly<Record<Die, readonly (readonly [number, number])[]>> = {
  1: [[50, 50]],
  2: [[28, 28], [72, 72]],
  3: [[28, 28], [50, 50], [72, 72]],
  4: [[28, 28], [72, 28], [28, 72], [72, 72]],
  5: [[28, 28], [72, 28], [50, 50], [28, 72], [72, 72]],
  6: [[28, 25], [72, 25], [28, 50], [72, 50], [28, 75], [72, 75]],
};

interface DieTheme {
  readonly body: string;
  readonly pip: string;
}

export const dieTheme = (color: DiceColor, which: 1 | 2): DieTheme => {
  if (color === 'redYellow') {
    return which === 1 ? { body: '#c9372c', pip: '#fdf6ec' } : { body: '#f3c534', pip: '#1d1a14' };
  }
  return { body: '#f7f3ea', pip: '#1b1b1b' };
};

const HEX6 = /^#([0-9a-f]{6})$/i;

/** linear mix of a #rrggbb colour towards white (255) or black (0) */
const mix = (hex: string, target: 0 | 255, t: number): string => {
  const m = HEX6.exec(hex);
  if (m === null || m[1] === undefined) throw new Error(`invalid colour: ${hex}`);
  const n = parseInt(m[1], 16);
  return `#${[n >> 16, (n >> 8) & 255, n & 255]
    .map((c) => Math.round(c + (target - c) * t).toString(16).padStart(2, '0'))
    .join('')}`;
};
export const lighten = (hex: string, t: number): string => mix(hex, 255, t);
export const darken = (hex: string, t: number): string => mix(hex, 0, t);

// face occupies (3,3)–(97,97); pip layout is defined on a 100×100 grid and mapped onto it
const FACE = { x: 3, y: 3, size: 94 } as const;
const pipPos = ([x, y]: readonly [number, number]): [number, number] => [
  FACE.x + (x * FACE.size) / 100,
  FACE.y + (y * FACE.size) / 100,
];

/**
 * A die drawn as a softly rounded cube seen from straight above: the face is shaded
 * symmetrically (light centre → darker rim) so it bulges without any directional light.
 * Pips stay flat; the only shadow is outside the silhouette (CSS drop-shadow).
 * `id` must be unique per die on the page (gradient ids).
 */
export const dieSvg = (value: Die | null, theme: DieTheme, id: string): string => {
  const pips = value === null ? [] : PIPS[value];
  const label = value === null ? 'まだ振っていません' : `出目 ${value}`;
  const pipMarkup = pips
    .map(pipPos)
    .map(([x, y]) => `<circle cx="${x}" cy="${y}" r="9" fill="${theme.pip}"/>`)
    .join('');
  return `<svg viewBox="0 0 100 100" role="img" aria-label="${label}">
  <defs>
    <radialGradient id="${id}-face" cx="0.5" cy="0.5" r="0.72">
      <stop offset="0" stop-color="${lighten(theme.body, 0.3)}"/>
      <stop offset="0.6" stop-color="${theme.body}"/>
      <stop offset="0.88" stop-color="${darken(theme.body, 0.08)}"/>
      <stop offset="1" stop-color="${darken(theme.body, 0.2)}"/>
    </radialGradient>
  </defs>
  <rect x="${FACE.x}" y="${FACE.y}" width="${FACE.size}" height="${FACE.size}" rx="22" fill="url(#${id}-face)" stroke="${darken(theme.body, 0.35)}" stroke-opacity=".55" stroke-width="1"/>
  ${value === null ? `<text x="50" y="62" text-anchor="middle" font-size="34" fill="${theme.pip}" opacity=".35">?</text>` : ''}
  ${pipMarkup}
</svg>`;
};

// ---------------------------------------------------------------------------
// histogram (observed vs. theoretical triangle)

const fmtPct = (p: number): string => `${Math.round(p * 100)}%`;

export const histogramSvg = (stats: readonly SumStat[], total: number): string => {
  const W = 520;
  const H = 300;
  const m = { l: 40, r: 10, t: 22, b: 30 };
  const iw = W - m.l - m.r;
  const ih = H - m.t - m.b;
  const peak = Math.max(...stats.map((s) => Math.max(s.observed, s.expected)));
  // "nice" grid step so that there are at most ~5 grid lines
  const step = [0.05, 0.1, 0.2, 0.25, 0.5].find((st) => (peak * 1.12) / st <= 5) ?? 0.5;
  const yMax = Math.min(1, Math.max(0.2, Math.ceil((peak * 1.12) / step) * step));
  const y = (p: number): number => m.t + ih - (p / yMax) * ih;
  const slot = iw / stats.length;

  const grid: string[] = [];
  for (let p = 0; p <= yMax + 1e-9; p += step) {
    grid.push(
      `<line x1="${m.l}" x2="${W - m.r}" y1="${y(p)}" y2="${y(p)}" class="grid"/>` +
        `<text x="${m.l - 6}" y="${y(p) + 4}" text-anchor="end" class="axis">${fmtPct(p)}</text>`,
    );
  }

  const bars = stats.map((s, i) => {
    const cx = m.l + slot * (i + 0.5);
    const ew = slot * 0.84;
    const ow = slot * 0.46;
    const seven = s.sum === 7 ? ' seven' : '';
    const expected = `<rect x="${cx - ew / 2}" y="${y(s.expected)}" width="${ew}" height="${y(0) - y(s.expected)}" rx="3" class="expected"><title>理論値 ${s.sum}: ${(s.expected * 100).toFixed(1)}%</title></rect>`;
    const observed =
      total > 0 && s.count > 0
        ? `<rect x="${cx - ow / 2}" y="${y(s.observed)}" width="${ow}" height="${y(0) - y(s.observed)}" rx="3" class="observed${seven}"><title>実測 ${s.sum}: ${s.count}回 (${(s.observed * 100).toFixed(1)}%)</title></rect>`
        : '';
    const count = s.count > 0 ? `<text x="${cx}" y="${y(s.observed) - 6}" text-anchor="middle" class="count${seven}">${s.count}</text>` : '';
    const label = `<text x="${cx}" y="${H - m.b + 19}" text-anchor="middle" class="xlabel${seven}">${s.sum}</text>`;
    return expected + observed + count + label;
  });

  return `<svg viewBox="0 0 ${W} ${H}" class="histogram" role="img" aria-label="出目の合計の分布（${total}投）">
  ${grid.join('')}
  ${bars.join('')}
  <line x1="${m.l}" x2="${W - m.r}" y1="${y(0)}" y2="${y(0)}" class="baseline"/>
</svg>`;
};

// ---------------------------------------------------------------------------
// KATAN register visualisation

const hex = (v: bigint, digits: number): string => v.toString(16).padStart(digits, '0');

const cellsSvg = (value: number, length: number, cls: string): string => {
  const size = 11;
  const gap = 2;
  const width = length * (size + gap) - gap;
  const cells: string[] = [];
  // MSB on the left
  for (let i = length - 1, col = 0; i >= 0; i--, col++) {
    const bit = Math.floor(value / 2 ** i) % 2;
    cells.push(`<rect x="${col * (size + gap)}" y="0" width="${size}" height="${size}" rx="2" class="${bit ? 'on' : 'off'}"/>`);
  }
  return `<svg viewBox="0 0 ${width} ${size}" width="${width}" height="${size}" class="reg ${cls}">${cells.join('')}</svg>`;
};

export interface CipherViewModel {
  readonly counter: number | null;
  readonly round: number;
  readonly snapshot: RegisterSnapshot | null;
  /** present once encryption is complete */
  readonly blocks: readonly BlockInfo[] | null;
}

export const cipherViewHtml = (vm: CipherViewModel): string => {
  if (vm.counter === null || vm.snapshot === null) {
    return `<div class="cipher-empty">サイコロを振ると、KATAN64 の内部レジスタと暗号文から出目を取り出す様子がここに表示されます。</div>`;
  }
  const plaintext = (BigInt(vm.counter) << 8n).toString(16).padStart(16, '0');
  const first = vm.blocks?.[0];
  const sides = ['左', '右'];
  let usedSoFar = 0;
  const chunks =
    first === undefined
      ? Array.from({ length: 21 }, () => `<span class="chunk pending">·</span>`).join('')
      : first.chunks
          .map((c, i) => {
            const bits = c.value.toString(2).padStart(3, '0');
            const title = `bit ${3 * i + 2}〜${3 * i}: ${bits}₂ = ${c.value}`;
            if (c.status === 'used') {
              const side = sides[usedSoFar++] ?? '';
              return `<span class="chunk used" title="${title} → 目 ${c.value + 1}"><em>${side}</em>${c.value}<small>→${c.value + 1}</small></span>`;
            }
            const why = c.status === 'rejected' ? '（6・7 は捨てる）' : '（2つ揃った後なので使わない）';
            return `<span class="chunk ${c.status}" title="${title}${why}">${c.value}</span>`;
          })
          .join('');
  const extra =
    vm.blocks !== null && vm.blocks.length > 1
      ? `<div class="cipher-note">1ブロック目で2つ揃わなかったため、平文 n‖1 以降のブロック ${vm.blocks.length} まで使用</div>`
      : '';
  return `<div class="cipher-head">
    <span class="tag">KATAN64</span>
    <span>平文 P = n‖0 = <code>0x${plaintext}</code></span>
    <span class="round">round <b>${String(vm.round).padStart(3, ' ')}</b>/254</span>
  </div>
  <div class="regs">
    <div class="reg-row"><span class="reg-label">L1</span>${cellsSvg(vm.snapshot.l1, 25, 'l1')}</div>
    <div class="reg-row"><span class="reg-label">L2</span>${cellsSvg(vm.snapshot.l2, 39, 'l2')}</div>
  </div>
  <div class="cipher-out">
    <span>暗号文 C = <code>${first === undefined ? '…' : `0x${hex(first.ciphertext, 16)}`}</code></span>
  </div>
  <div class="chunk-explain">
    <span>C を<b>下位ビット（16進の右端）から 3bit ずつ</b>区切って 0〜7 の数にし、左から順に判定します：</span>
    <span class="rule"><i class="used"></i>0〜5 → +1 してサイコロの目に採用（先に採用した方が左）</span>
    <span class="rule"><i class="rejected"></i>6・7 → 捨てる（8通りを6つの目に均等に割り振れず偏るため）</span>
    <span class="rule"><i class="unused"></i>2つ揃った後は使わない</span>
  </div>
  <div class="chunks" aria-label="暗号文を下位ビットから3bitずつ区切った値"><span class="chunks-lead">下位→</span>${chunks}</div>
  ${extra}`;
};

// ---------------------------------------------------------------------------
// recent rolls

/** chronological (old → new, left → right) to match ◀ 戻る / 進む ▶ */
export const recentHtml = (log: readonly Roll[], limit: number, currentCounter: number | null): string => {
  const items = log.slice(-limit);
  if (items.length === 0) return `<span class="recent-empty">履歴なし</span>`;
  return items
    .map((r) => {
      const s = sumOf(r);
      const cls = [r.status, s === 7 ? 'seven' : '', r.counter === currentCounter ? 'current' : ''].filter(Boolean).join(' ');
      const status = r.status === 'active' ? '' : r.status === 'undone' ? '（取消中：→で戻せます）' : '（取消）';
      return `<span class="chip ${cls}" title="#${r.counter + 1}: ${r.d1} + ${r.d2} = ${s}${status}">${s}</span>`;
    })
    .join('');
};

export const formatElapsed = (ms: number): string => {
  const total = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const mmss = `${String(m).padStart(h > 0 ? 2 : 1, '0')}:${String(s).padStart(2, '0')}`;
  return h > 0 ? `${h}:${mmss}` : mmss;
};
